function g(topic,nzLink,iDo,weDo,youDo,aos){return{topic,nzLink,iDo,weDo,youDo,aos:aos||[]}}
window.__WWU_TERM_DATA=window.__WWU_TERM_DATA||{};
window.__WWU_TERM_DATA[2]={1:{Monday:g("Tier 2 vocabulary: words for movement & action","Writing — Vocabulary (Knowledge & Practice): precise verbs eliminate vague movement words; students select verbs that convey manner and quality of movement, reducing reliance on weak constructions.",{title:"I Do — Swap the Vague Movement Verb",instruction:"Watch me swap plain movement verbs for precise ones that carry more information.",example:'"The man went down the street." → "The man <u>strode</u> down the street."',demonstration:'Went → strode, shuffled, sprinted, lurched. Each verb tells us HOW as well as that movement happened. "Strode" tells us purposeful, confident movement. "Shuffled" tells us tired or reluctant movement. One word replaces a verb + adverb.',tip:'Precise verbs eliminate the need for adverbs: "ran quickly" → "sprinted."'},{title:"We Do — Upgrade the Verb",instruction:"Upgrade the underlined verbs with more precise movement words.",sentences:["The bird <u>went</u> through the air.","She <u>moved</u> across the dance floor.","He <u>went</u> into the room."],prompt:'What does the precise verb tell us that "went" does not?'},{title:"You Do — Your Turn",instruction:"Replace each plain verb with the most precise one you can think of.",tasks:["The snake <u>went</u> through the grass.","The toddler <u>moved</u> towards the door.","She <u>went</u> across the rooftops.","✦ Bonus: Write 4 sentences each using a different precise movement verb. No two the same."]},[{code:"Writing — Vocabulary (Knowledge)",label:"Precise verbs for movement",detail:'NZC Phase 2 Writing — Vocabulary (Knowledge): "Vocabulary is chosen deliberately for effect, so students consider the precision and connotations of words." Selecting a precise movement verb (strode, shuffled, lurched) rather than a generic one (went, moved) demonstrates Tier 2 vocabulary development — a core expectation at Years 5–6. Each verb carries manner, intent, and character without requiring additional adverbs.'},{code:"Writing — Vocabulary (Practice)",label:"Selecting verbs fit for purpose",detail:`NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases… that are fit for purpose and audience." This lesson builds the habit of interrogating verb choices — asking not just 'what is happening?' but 'exactly how is it happening?' — and finding the single word that answers both questions simultaneously.`}]),Tuesday:g("Nouns: collective & abstract nouns","Writing — Sentence Structure (Knowledge): nouns include common, proper, collective, and abstract types; understanding the full range of noun classes develops students' grammatical knowledge and expands their writing vocabulary.",{title:"I Do — Two Special Noun Types",instruction:"Collective nouns name a group. Abstract nouns name ideas, feelings, or concepts you cannot touch.",example:"Collective: a <u>flock</u> of birds | Abstract: <u>courage</u>, <u>freedom</u>, <u>justice</u>",demonstration:"Flock, swarm, pride, pod — these are collective. Justice, hope, anger — these are abstract. You can't hold justice in your hand, but it's a noun because it names a concept.",tip:"If you can't touch it or see it, but it's a thing — it's probably abstract."},{title:"We Do — Sort the Nouns",instruction:"Sort these nouns into collective, abstract, or concrete.",sentences:["a herd of cattle","curiosity","a bouquet of flowers","loyalty","a school of fish"],prompt:"How do you know? Could you take a photo of it? Touch it?"},{title:"You Do — Your Turn",instruction:"Label each noun: collective (C), abstract (A), or concrete (Co).",tasks:["a murder of crows —","envy —","a packet of biscuits —","a pride of lions —","determination —","✦ Bonus: Write a sentence for each type using a noun from today's lesson."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"Word classes: collective & abstract nouns",detail:'NZC Phase 2 Writing — Sentence Structure (Knowledge): "Words belong to different classes… nouns include common, proper, collective (naming a group), and abstract (naming a concept, idea, or emotion) types." Understanding the full range of noun classes deepens grammatical awareness and expands the vocabulary available to students when composing at Years 5–6.'},{code:"Writing — Vocabulary (Practice)",label:"Using abstract nouns for depth",detail:'NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases… that are fit for purpose and audience." Using abstract nouns deliberately — courage, justice, determination — is a hallmark of sophisticated writing at Phase 2, allowing students to write about ideas and values, not just concrete events.'}]),Wednesday:g("Simple sentences: revisit with action-verb focus","Writing — Sentence Structure (Practice): students revisit simple sentence structure with a focus on replacing weak verb constructions (do/make/give + noun) with single powerful action verbs.",{title:"I Do — One Strong Verb Beats Three Weak Words",instruction:'Revisiting simple sentences — but this time the focus is on choosing a powerful action verb over a weak "do + noun" construction.',example:'Weak: "The volcano did an explosion." → Strong: "The volcano <u>erupted</u>."',demonstration:'"Do + noun" is often the weak version. Replace with a direct action verb: made a decision → decided. Gave a performance → performed. Did an investigation → investigated. Each replacement tightens the sentence and strengthens the verb.',tip:'"Did", "made", "gave", "had" + noun = usually replaceable with one strong verb.'},{title:"We Do — Find the Strong Verb",instruction:'Replace the weak "do + noun" construction with one strong verb.',sentences:["She made a complaint about the noise.","They did a celebration when they won.","He gave a performance that amazed the crowd."],prompt:"What single verb can replace each phrase?"},{title:"You Do — Your Turn",instruction:"Rewrite each sentence using one strong action verb.",tasks:["She made a decision to leave early.","The team gave a demonstration of the new skill.","They did an investigation into the disappearance.","✦ Bonus: Write 5 simple sentences using 5 different powerful action verbs."]},[{code:"Writing — Sentence Structure (Practice)",label:"Strong action verbs in simple sentences",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write grammatically correct sentences" and to select verbs that convey meaning precisely. Replacing weak "do/make/give + noun" constructions with single powerful action verbs is a key revision skill — it tightens sentence structure and removes redundant words simultaneously.'},{code:"Writing — Vocabulary (Practice)",label:"Precise verb selection",detail:'NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases… that are fit for purpose and audience." This lesson reinforces that one exact verb (erupted, decided, investigated) is more powerful and precise than a vague verb + noun combination — a foundational principle of effective word choice at Phase 2.'}]),Thursday:g("Proofreading: capitals for proper nouns in context","Writing — Punctuation (Knowledge) & Writing Process (Practice): students apply capitalisation rules for proper nouns in complex, multi-sentence text, developing accuracy and consistency in editing.",{title:"I Do — Proper Nouns in Longer Text",instruction:"In this term's editing focus, we look specifically at proper noun capitals in longer, more complex text.",example:'"last tuesday, ms brown took class 5b to the otago museum in dunedin."',demonstration:'Fixed: "Last Tuesday, Ms Brown took Class 5B to the Otago Museum in Dunedin." Every specific name, title, day, place, and class identifier needs a capital.',tip:"Scan specifically for: days, months, place names, people's names/titles, specific event names."},{title:"We Do — Capital Letter Hunt",instruction:"Find and fix all the proper noun capitalisation errors.",sentences:["on anzac day, uncle mike and aunt sarah drove to hamilton for the dawn parade at memorial park."],prompt:"List every word that needs a capital. How many did you find?"},{title:"You Do — Your Turn",instruction:"Rewrite this passage with all proper noun capitals correctly placed.",tasks:["my cousin riya is visiting from tauranga next friday. she goes to otumoetai college and is in year 10. on saturday we're going to visit the national aquarium of new zealand in napier. riya wants to see the tuatara display and the kiwi house afterwards we might have lunch at the hawke's bay farmers market.","✦ Bonus: Write a paragraph about a real or imaginary trip. Include at least 6 proper nouns — all correctly capitalised."]},[{code:"Writing — Punctuation (Knowledge)",label:"Capitalisation: proper nouns in context",detail:'NZC Phase 2 Writing — Punctuation (Knowledge): "Capital letters are used at the start of sentences and for all proper nouns — names of specific people, places, days, months, titles, organisations, and events." At Phase 2, students are expected to apply this convention consistently across longer, more complex text where proper nouns appear frequently and in varied contexts.'},{code:"Writing — Writing Process (Practice)",label:"Editing for capitalisation accuracy",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing to check that it makes sense and is accurate, including checking for correct capitalisation." This lesson trains the targeted scanning strategy — reading specifically for proper nouns — that helps students catch capitalisation errors they overlook in a general read-through.'}])},2:{Monday:g("Commas after fronted adverbials","Writing — Punctuation (Knowledge & Practice): a fronted adverbial is followed by a comma; students apply this convention accurately and understand why the comma signals a pause before the main clause.",{title:"I Do — The Opener Comma",instruction:"When a sentence starts with an adverbial phrase or clause (a fronted adverbial), we put a comma after it before the main clause begins.",example:'"<u>After the long match,</u> the players collapsed on the grass." | "<u>During the school holidays,</u> we visited Rotorua."',demonstration:'"After the long match" is the fronted adverbial — it sets the scene. The comma after "match" separates it from the main clause. Without the comma, the reader rushes past the opener without pausing.',tip:"Read aloud. If you naturally pause after the opening phrase before the subject arrives — that pause is your comma."},{title:"We Do — Add the Comma",instruction:"These sentences have fronted adverbials but are missing the comma. Find the opener and add the comma.",sentences:["Before the sun had risen the fishing boats left the harbour.","On the last day of term the students performed their assembly item.","Despite the heavy rain the match went ahead as planned."],prompt:"Where does the fronted adverbial end and the main clause begin? That's where the comma goes."},{title:"You Do — Your Turn",instruction:"Add the missing comma to each sentence and write the type of fronted adverbial (time/place/contrast).",tasks:["Throughout the long journey south the waka stayed on course.","Although the trail was steep the tamariki kept climbing.","By the time the tide turned the divers were already back on shore.","✦ Bonus: Write 5 sentences that each begin with a different type of fronted adverbial. Use at least one time, one place, and one contrast opener."]},[{code:"Writing — Punctuation (Knowledge)",label:"Comma after fronted adverbials",detail:'NZC Phase 2 Writing — Punctuation (Knowledge): "When an adverbial word, phrase, or clause is placed before the subject at the start of a sentence (a fronted adverbial), a comma is used to separate it from the main clause." This is a specific and frequently tested punctuation convention at Years 5–6, appearing across narrative, recount, and persuasive writing.'},{code:"Writing — Punctuation (Practice)",label:"Applying fronted adverbial comma",detail:'NZC Phase 2 Writing — Punctuation (Practice): Students are expected to "use a range of punctuation accurately and for effect." The comma after a fronted adverbial is both a convention (accuracy) and a craft tool (effect) — it signals a deliberate pause that gives the opener its weight. This lesson builds the read-aloud checking strategy: the natural pause reveals where the comma belongs.'}]),Tuesday:g("Future tense: will & going to",'Writing — Sentence Structure (Knowledge): the future tense is expressed using "will" or "going to"; the choice between them carries different shades of meaning — spontaneous decisions vs planned intentions.',{title:"I Do — Two Ways to Talk About the Future",instruction:'English expresses future time in two main ways: "will" + verb, and "going to" + verb. They are not always interchangeable. Watch me use each one and explain the difference.',example:'"I <u>will</u> help you with that." (spontaneous decision) | "We <u>are going to</u> plant native trees next month." (planned intention)',demonstration:`"Will" is used for spontaneous decisions, offers, predictions, and promises made at the moment of speaking. "Going to" is used for plans already decided and for predictions based on current evidence. "Look at those clouds — it's going to rain." (evidence right there).`,tip:"Planned ahead → going to. Decided right now → will. Evidence in front of you → going to."},{title:"We Do — Will or Going To?",instruction:'Choose "will" or "going to" and explain why.',sentences:["The marae committee ___ (will/is going to) hold a hui next Saturday — it's been in the calendar for months.",`"I can't carry that box." "Don't worry, I ___ (will/am going to) help you."`,"Look at those storm clouds — the weather ___ (will/is going to) turn soon."],prompt:"Is this a plan, a spontaneous offer, or a prediction based on evidence?"},{title:"You Do — Your Turn",instruction:"Complete each sentence with the correct future form. Write a brief reason for your choice.",tasks:["The school ___ (will/is going to) hold a matariki celebration — we've been practising for weeks.",'"The printer is broken." "I ___ (will/am going to) fix it." (spontaneous offer)',"That kūmara plant ___ (will/is going to) need water soon — the soil is bone dry.",`✦ Bonus: Write a paragraph of 5 sentences about a future event you're genuinely planning. Use "going to" for plans and "will" for predictions or promises within it.`]},[{code:"Writing — Sentence Structure (Knowledge)",label:"Future tense: will & going to",detail:`NZC Phase 2 Writing — Sentence Structure (Knowledge): "The future tense in English is expressed using 'will' + verb (for spontaneous decisions, offers, and promises) or 'going to' + verb (for pre-planned intentions and predictions based on present evidence). Understanding the distinction allows writers to express future time with precision rather than using the two forms interchangeably."`},{code:"Writing — Sentence Structure (Practice)",label:"Using future tense accurately",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write grammatically correct sentences" using a range of tenses accurately. Choosing between "will" and "going to" is a nuanced grammar decision that requires students to consider the context and intended meaning — a marker of grammatical sophistication at Years 5–6.'}]),Wednesday:g("Compound sentences: new contexts & conjunctions","Writing — Sentence Structure (Practice): students use FANBOYS conjunctions in new writing contexts — recount, report, and argument — understanding that the same conjunction carries different weight depending on purpose and audience.",{title:"I Do — FANBOYS in Fresh Contexts",instruction:"We know FANBOYS conjunctions (for, and, nor, but, or, yet, so). This week we use them in new writing contexts to see how the same conjunction does different jobs.",example:'Recount: "We arrived at Tāmaki Makaurau, <u>and</u> the whole whānau was waiting." | Argument: "The policy is popular, <u>yet</u> the evidence does not support it."',demonstration:'"And" adds. "But/yet" contrasts. "So" shows result. "Or" gives alternatives. "For" gives reason (formal). "Nor" adds a negative. The conjunction you choose shapes the relationship between the two ideas.',tip:"Before picking a conjunction, decide: am I adding, contrasting, showing a result, or giving a reason? That decides which FANBOYS fits."},{title:"We Do — Choose the Right FANBOYS",instruction:"Join each pair of sentences with the best FANBOYS conjunction. Add a comma before the conjunction.",sentences:["The hīkoi had been going for three days. The marchers showed no sign of stopping.","You can present your findings as a poster. You can create a short video.","The experiment failed the first time. The team learnt something valuable from it."],prompt:"What is the relationship between the two ideas? That decides the conjunction."},{title:"You Do — Your Turn",instruction:"Write a compound sentence for each context using the conjunction given.",tasks:['Write about a kaitiakitanga project using "so."','Write about a time something went wrong using "yet."','Write a sentence giving someone two choices using "or."',"✦ Bonus: Write a paragraph about an environmental issue. Use at least three different FANBOYS conjunctions. Underline each one."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"FANBOYS in varied contexts",detail:'NZC Phase 2 Writing — Sentence Structure (Knowledge): "Coordinating conjunctions (for, and, nor, but, or, yet, so) join two independent clauses of equal grammatical weight. Each conjunction signals a different relationship: addition (and), contrast (but/yet), result (so), alternative (or), reason (for), negative addition (nor)." Students learn that the same conjunction carries different register and weight depending on text type and context.'},{code:"Writing — Sentence Structure (Practice)",label:"Compound sentences across text types",detail:`NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write a variety of sentence structures for effect and clarity" across different text types. This lesson extends compound sentence use beyond narrative into recount, report, and argument — building students' ability to select the right conjunction for the relationship and context, not just the first one that fits grammatically.`}]),Thursday:g("Editing: fixing comma splices","Writing — Punctuation (Knowledge) & Writing Process (Practice): a comma splice joins two independent clauses with only a comma; students identify comma splices and correct them using a full stop, semicolon, or conjunction.",{title:"I Do — The Comma That Tries to Do Too Much",instruction:"A comma splice is when two complete sentences are joined with just a comma. A comma is not strong enough to hold two independent clauses together on its own. Watch me find and fix one.",example:'✗ "The waka was ready, the crew climbed aboard." → ✓ "The waka was ready. The crew climbed aboard." OR ✓ "The waka was ready, and the crew climbed aboard." OR ✓ "The waka was ready; the crew climbed aboard."',demonstration:"Three fixes: (1) full stop — two separate sentences. (2) comma + conjunction — compound sentence. (3) semicolon — joins two closely related sentences. All three are correct. Choose based on the relationship between the ideas.",tip:"Test: read each side of the comma. If both could stand alone as sentences — the comma is a splice. Fix it."},{title:"We Do — Fix the Splice",instruction:"Find the comma splice in each sentence and fix it three ways.",sentences:["The tide was coming in, we had to leave quickly.","She had been training for months, the race was finally here."],prompt:"Which fix sounds best for each sentence? Does the relationship between the ideas affect your choice?"},{title:"You Do — Your Turn",instruction:"Fix each comma splice using the method shown in brackets.",tasks:["The kākāpō is critically endangered, conservation efforts have helped increase numbers. [semicolon]","The hail hammered the roof, everyone moved away from the windows. [conjunction]","She had practised the speech a hundred times, she still felt her hands shake. [full stop]","✦ Bonus: Write 3 pairs of sentences — then deliberately create a comma splice, and fix it in two different ways each time."]},[{code:"Writing — Punctuation (Knowledge)",label:"Comma splices",detail:`NZC Phase 2 Writing — Punctuation (Knowledge): "A comma splice occurs when two independent clauses are joined with only a comma, which is insufficient punctuation. It can be corrected by: (1) replacing the comma with a full stop; (2) adding a coordinating conjunction after the comma; or (3) replacing the comma with a semicolon." Understanding comma splices deepens students' knowledge of sentence boundaries and punctuation function.`},{code:"Writing — Writing Process (Practice)",label:"Identifying and correcting comma splices",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing to check that it makes sense and is accurate." Recognising and fixing comma splices is a targeted editing skill that requires students to identify sentence boundaries and select the punctuation or conjunction that best expresses the relationship between the two clauses.'}])},3:{Monday:g("Antonyms & shades of meaning","Writing — Vocabulary (Knowledge): antonyms are words with opposite meanings; understanding the spectrum between antonyms develops nuanced vocabulary and helps students select words with the right shade of meaning.",{title:"I Do — The Meaning Spectrum",instruction:"Antonyms are opposites — but between most opposites there's a whole spectrum of words. Understanding that spectrum lets you choose exactly the right word for your meaning.",example:`hot ←——————————————→ cold
scalding / burning / warm / tepid / cool / chilly / freezing / arctic`,demonstration:'"Hot" and "cold" are antonyms, but the spectrum between them has eight gradations. "The water was cold" is vague. "The water was arctic" is precise. Choosing from the spectrum — rather than defaulting to the antonym — gives writing its precision and texture.',tip:"Before writing a describing word, ask: where on the spectrum between the two extremes does this fall? Then find the word that sits exactly there."},{title:"We Do — Build the Spectrum",instruction:"Build meaning spectrums for each pair of antonyms. Aim for at least five words between the two extremes.",sentences:["happy ←—————————→ sad","loud ←—————————→ quiet","fast ←—————————→ slow"],prompt:"Which word on the spectrum best describes: a library, a sports crowd, a funeral? Why?"},{title:"You Do — Your Turn",instruction:"Choose the word from the spectrum that best fits each context. Explain your choice.",tasks:["The old man's voice was ___ (choose from: booming / loud / clear / soft / faint / inaudible) as he told the story.","After the marathon, the runner felt ___ (choose from: exhausted / tired / weary / drained / spent / destroyed).","The stream moved ___ (choose from: rushing / flowing / trickling / seeping / still) through the valley.","✦ Bonus: Choose one antonym pair. Build a spectrum of 8 words. Then use three of them in three separate sentences about the same setting."]},[{code:"Writing — Vocabulary (Knowledge)",label:"Antonyms & meaning spectrums",detail:'NZC Phase 2 Writing — Vocabulary (Knowledge): "The meaning of words can be extended or changed by context; vocabulary is chosen deliberately for effect, so students consider the connotations and precision of words." Understanding antonyms and the spectrum of meaning between them is a key component of Tier 2 vocabulary development — it moves students beyond binary word choice (hot/cold) to nuanced selection along a continuum.'},{code:"Writing — Vocabulary (Practice)",label:"Selecting words for precision",detail:`NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases, including subject-specific vocabulary, that are fit for purpose and audience" and to "consider the effect of word choice on the reader." This lesson develops the habit of asking 'exactly where on the spectrum does this fall?' before committing to a word — the key discipline of precise vocabulary selection.`}]),Tuesday:g("Subject-verb agreement: tricky cases (everyone, each)","Writing — Sentence Structure (Knowledge): indefinite pronouns such as everyone, each, neither, and someone are grammatically singular and require singular verb forms, even when they refer to multiple people.",{title:"I Do — The Tricky Singular Words",instruction:"Most subject-verb agreement is straightforward. But some words look plural and feel plural yet are grammatically singular.",example:'"<u>Everyone</u> in the two classes <u>was</u> invited." (not "were") | "<u>Each</u> of the players <u>has</u> a number." (not "have")',demonstration:'"Everyone," "everybody," "someone," "nobody," "each," "either," "neither" — all singular, even when they refer to many people. The trick: mentally replace with "every single person" — then the singular verb feels natural.',tip:'Everyone/each/either/neither/nobody = singular. Replace with "every single one" in your head — the right verb follows naturally.'},{title:"We Do — Choose the Right Verb",instruction:"Choose the correct verb form for each sentence.",sentences:["Everyone in the kapa haka group ___ (know/knows) the words.","Each of the entries ___ (was/were) judged on three criteria.","Neither of the referees ___ (was/were) happy with the decision."],prompt:'Replace the subject with "every single one" — which verb sounds right now?'},{title:"You Do — Your Turn",instruction:"Correct the subject-verb agreement error in each sentence.",tasks:["Everyone in the syndicate have submitted their work.","Each of the kūmara plants were carefully watered.","Neither of the answers are correct.","Somebody have left their bag on the mat.","✦ Bonus: Write 5 sentences, each using one of these subjects: everyone, each, neither, somebody, anyone. Make sure agreement is correct in every one."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"SVA: indefinite pronouns",detail:'NZC Phase 2 Writing — Sentence Structure (Knowledge): "Indefinite pronouns (everyone, everybody, someone, nobody, each, either, neither) are grammatically singular and require singular verb forms, even when they refer to multiple people or things. Errors in agreement with these pronouns are among the most common grammar mistakes at Years 5–6." Students learn to override the "feels plural" instinct by testing with "every single one."'},{code:"Writing — Writing Process (Practice)",label:"Editing for tricky SVA",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing to check that it makes sense and is accurate." Identifying and correcting tricky subject-verb agreement errors — particularly with indefinite pronouns — requires students to understand the grammatical subject of the clause, not just the nearest noun, and is a key editing skill at Phase 2.'}]),Wednesday:g('Expanding sentences using "when" and "because"','Writing — Sentence Structure (Practice): students expand simple sentences by adding subordinate clauses using "when" and "because" to show time relationships and causation.',{title:"I Do — Add the Why and the When",instruction:'Two of the most useful subordinating conjunctions for expanding sentences are "when" (time) and "because" (cause/reason). Watch me use them to transform bare sentences.',example:'Base: "The crowd cheered." → + when: "The crowd cheered <u>when the final whistle blew</u>." → + because: "The crowd cheered <u>because the home team had just equalised</u>."',demonstration:'"When" tells us the time — the moment the action happened. "Because" tells us the cause — why it happened. Each adds a whole new layer of meaning to the same simple sentence. I can also put the "when/because" clause first: "When the final whistle blew, the crowd cheered."',tip:'"When" answers: at what moment? "Because" answers: for what reason? Add the one your sentence is missing.'},{title:"We Do — Expand Together",instruction:'Expand each sentence by adding a "when" clause AND a "because" clause. Try both.',sentences:["The pohutukawa bloomed.","The students fell silent.","The explorer turned back."],prompt:"Which expansion is more interesting for each sentence — the when or the because? Why?"},{title:"You Do — Your Turn",instruction:"Expand each sentence with the conjunction shown. Try putting the clause at the start AND at the end.",tasks:["The river flooded. [because]","The kiwi came out. [when]","She changed her mind. [because]","The lights went out. [when]",'✦ Bonus: Write a paragraph of 5 sentences. Use "when" in at least two and "because" in at least two. Vary whether the clause comes first or last.']},[{code:"Writing — Sentence Structure (Practice)",label:'Expanding with "when" & "because"',detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "expand simple sentences by adding words, phrases, and clauses to add detail and description," including using subordinating conjunctions to express time (when) and cause (because). This lesson revisits and deepens Term 1 complex sentence work in a fresh context, reinforcing that clause order is flexible and that the fronted version requires a comma.'},{code:"Writing — Sentence Structure (Knowledge)",label:"Subordinating conjunctions: time & cause",detail:`NZC Phase 2 Writing — Sentence Structure (Knowledge): "'When' is a subordinating conjunction that introduces a clause expressing time; 'because' introduces a clause expressing cause or reason. Both create complex sentences where one clause depends on the other for full meaning." Understanding the semantic difference between these two conjunctions helps students choose the right one for the relationship they want to express.`}]),Thursday:g("Editing: upgrading bland verbs in a passage","Writing — Vocabulary (Practice) & Writing Process (Practice): students identify weak, overused verbs in a passage and replace them with precise verbs that carry meaning, character, and energy.",{title:"I Do — Bland Verbs Drain Energy",instruction:"Some verbs are so vague they tell us almost nothing: went, got, said, did, made, was. Watch me identify them in a passage and replace them with verbs that do real work.",example:'"The children <u>went</u> to the beach. They <u>got</u> into the water. Dad <u>said</u> they should come out."',demonstration:'"went" → "raced" | "got" → "plunged" | "said" → "bellowed". New version: "The children <u>raced</u> to the beach. They <u>plunged</u> into the water. Dad <u>bellowed</u> at them to come out." The scene comes alive.',tip:'Highlight every "went," "got," "said," "did," "made," "was" in a passage. Each one is an upgrade opportunity.'},{title:"We Do — Upgrade the Passage",instruction:"Replace every underlined bland verb with a more precise one. The new verb must match the context.",sentences:["The kererū <u>went</u> from branch to branch, <u>getting</u> the ripest berries. It <u>made</u> a loud noise with its wings as it <u>went</u> away."],prompt:`What is actually happening physically? What does a precise verb tell the reader that "went" and "got" don't?`},{title:"You Do — Your Turn",instruction:"Rewrite this passage, upgrading every bland verb you can find.",tasks:["On field trip day, the class got on the bus early. They went to the wetland reserve near Ōtaki. The guide said something about the different birds. Some students went into the hide and got photos of a bittern. Everyone said it was great.","✦ Bonus: Count how many bland verbs you replaced. Write the before and after side by side. Which passage is more engaging and why?"]},[{code:"Writing — Vocabulary (Practice)",label:"Upgrading bland verbs",detail:`NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases… that are fit for purpose and audience" and to "consider the effect of word choice on the reader." This lesson targets the most common verb weakness in Years 5–6 writing — overuse of generic verbs (went, got, said) — and builds the habit of asking 'what is ACTUALLY happening?' before selecting a more precise alternative.`},{code:"Writing — Writing Process (Practice)",label:"Verb audit in revision",detail:`NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing… making changes to vocabulary, punctuation, and structure to improve clarity and impact." The verb audit — highlighting every weak verb and asking if it can be upgraded — is a targeted revision strategy that directly improves the energy and precision of students' writing at Phase 2.`}])},4:{Monday:g("Apostrophes for contraction","Writing — Punctuation (Knowledge): a contraction apostrophe replaces omitted letters when two words are joined; students apply contraction apostrophes accurately and distinguish them from possessive apostrophes.",{title:"I Do — The Apostrophe That Replaces Letters",instruction:"A contraction apostrophe shows where one or more letters have been removed when two words are joined together.",example:`"do not" → "don't" (the apostrophe replaces the 'o') | "they are" → "they're" | "I would" → "I'd"`,demonstration:`"cannot" → "can't" — the apostrophe replaces "no". "would not" → "wouldn't" — replaces "o". "she is" → "she's" — replaces "i". The apostrophe sits exactly where the missing letters were.`,tip:"The apostrophe goes WHERE THE LETTERS WERE REMOVED — not just anywhere between the words."},{title:"We Do — Contract and Expand",instruction:"Write the contraction for each pair of words, and expand each contraction back to the full form.",sentences:["we will → ___  |  it's → ___","have not → ___  |  they'd → ___","I am → ___  |  couldn't → ___"],prompt:`Exactly which letters did the apostrophe replace? Could you be confused between "it's" (it is) and "its" (belonging to it)?`},{title:"You Do — Your Turn",instruction:"Fix the apostrophe errors in these sentences — some are missing, some are in the wrong place.",tasks:["Sh'es not sure if theyre coming to the hangi tonight.","I wo'nt be ready until the bus ha's already left.","Weve been waiting here for ages — it isnt fair.","They're dog isnt allowed inside but its a cold night.","✦ Bonus: Write a conversation (6 lines of dialogue) between two friends making plans. Use at least 6 different contractions correctly."]},[{code:"Writing — Punctuation (Knowledge)",label:"Contraction apostrophes",detail:`NZC Phase 2 Writing — Punctuation (Knowledge): "A contraction apostrophe replaces the letter or letters omitted when two words are combined (e.g. do not → don't, they are → they're, I would → I'd). The apostrophe is placed exactly where the letters were removed." Students also practise distinguishing contraction apostrophes from possessive apostrophes — a critical and frequently confused distinction at Years 5–6.`},{code:"Writing — Punctuation (Practice)",label:"Applying contraction apostrophes accurately",detail:'NZC Phase 2 Writing — Punctuation (Practice): Students are expected to "use a range of punctuation accurately and for effect," including apostrophes for contraction. The key test — expanding the contraction to check whether the apostrophe placement makes sense — gives students a reliable self-checking strategy they can apply independently when editing their own writing.'}]),Tuesday:g("Relative pronouns: who, which, that","Writing — Sentence Structure (Knowledge): relative pronouns (who, which, that) introduce relative clauses that give additional information about a noun; the choice of pronoun and use of commas depends on whether the clause defines or adds extra information.",{title:"I Do — Clauses That Give Extra Information",instruction:`A relative clause is a type of subordinate clause that gives more information about a noun. It's introduced by a relative pronoun: "who" (for people), "which" (for things), "that" (for people or things in defining clauses).`,example:'"The woman <u>who won the award</u> is our neighbour." | "The bridge<u>, which was built in 1902,</u> is being restored." | "The book <u>that she recommended</u> was brilliant."',demonstration:'"who" → refers back to a person. "which" → refers back to a thing, adds non-essential info (use commas): "The river, which floods every winter, is rising again." "that" → defines which one (no commas): "The path that leads to the pā is steep."',tip:'"Who" = people. "Which" = things + commas (extra info). "That" = defines which one, no commas.'},{title:"We Do — Choose the Right Relative Pronoun",instruction:"Complete each sentence with who, which, or that.",sentences:["The rangatira ___ led the iwi was known for her wisdom.","The old pōhutukawa, ___ had stood for 300 years, was finally protected.","This is the exact track ___ leads to the summit."],prompt:"Does the clause define which one, or add extra information? Does it refer to a person or a thing?"},{title:"You Do — Your Turn",instruction:"Add a relative clause to each sentence using the pronoun given.",tasks:["The scientist ___ (who) discovered the new species published her findings last month.","Rotorua, ___ (which) is famous for its geothermal activity, attracts tourists year-round.","She finally found the notebook ___ (that) she had been searching for all morning.","✦ Bonus: Write a paragraph about a local place or person. Include at least three relative clauses — one with who, one with which (with commas), and one with that."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"Relative pronouns & relative clauses",detail:`NZC Phase 2 Writing — Sentence Structure (Knowledge): "Relative pronouns (who, which, that) introduce relative clauses that modify a noun. 'Who' refers to people; 'which' refers to things and introduces non-defining (parenthetical) clauses set off with commas; 'that' introduces defining clauses with no commas." Mastering this distinction is a key grammar milestone at Phase 2, with direct implications for comma use.`},{code:"Writing — Sentence Structure (Practice)",label:"Using relative clauses for detail",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "expand sentences by adding clauses to add detail and description." Relative clauses are a sophisticated tool for embedding additional information about a noun within a sentence — avoiding the need for a separate sentence and creating more fluent, complex writing at Years 5–6.'}]),Wednesday:g("Topic sentences for persuasive paragraphs","Writing — Text Structure (Knowledge & Practice): persuasive topic sentences state a clear position or claim; students write topic sentences that introduce the paragraph argument and signal the writer's stance.",{title:"I Do — Topic Sentences That Argue",instruction:"In Term 1 we wrote topic sentences for informational paragraphs. This week, topic sentences carry an opinion or argument — they tell the reader not just what the paragraph is about, but what position you're taking.",example:'Informational: "Recycling reduces waste sent to landfill." | Persuasive: "<u>Recycling is not enough — we must stop producing unnecessary plastic altogether.</u>"',demonstration:`The persuasive topic sentence does three jobs: (1) introduces the paragraph's main idea, (2) makes the writer's position clear, (3) makes the reader want to know the evidence. "Everyone deserves access to clean water" is both a topic sentence AND an argument.`,tip:"A strong persuasive topic sentence takes a clear position. If someone could disagree with it — it's persuasive. If it's just a fact — it's informational."},{title:"We Do — Upgrade to Persuasive",instruction:"Turn each informational topic sentence into a persuasive one by adding a position or claim.",sentences:["Smartphones are used by many young people.","Schools have canteens that sell food to students.","Exercise has effects on health."],prompt:"What position could a writer take on each topic? Add the opinion to make it genuinely persuasive."},{title:"You Do — Your Turn",instruction:"Write a persuasive topic sentence for each argument prompt.",tasks:["Topic: whether students should have homework.","Topic: whether animals should be kept in zoos.","Topic: whether Aotearoa should have a four-day school week.","✦ Bonus: Choose one topic and write the full paragraph — topic sentence + at least two pieces of evidence or reasoning."]},[{code:"Writing — Text Structure (Knowledge)",label:"Persuasive topic sentences",detail:`NZC Phase 2 Writing — Text Structure (Knowledge): "In persuasive writing, each paragraph is organised around a claim or position introduced in the topic sentence. A persuasive topic sentence makes the writer's stance clear and invites the reader to consider the supporting evidence that follows." Students learn that a topic sentence in argument writing must be contestable — if no one could disagree with it, it is not yet persuasive.`},{code:"Writing — Text Structure (Practice)",label:"Structuring persuasive paragraphs",detail:'NZC Phase 2 Writing — Text Structure (Practice): Students are expected to "organise ideas into paragraphs with a clear main idea, supported by relevant detail" across a range of text types including persuasion. This lesson builds the skill of leading with a clear position before providing evidence — a structural discipline that is foundational to effective persuasive writing at Phase 2.'}]),Thursday:g("Editing: removing unnecessary apostrophes","Writing — Punctuation (Knowledge) & Writing Process (Practice): apostrophes are not used to form plurals; students identify and remove apostrophes used incorrectly in plural nouns.",{title:"I Do — The Apostrophe That Shouldn't Be There",instruction:"One of the most common apostrophe errors is using one to make a word plural. Apostrophes are NEVER used for plurals — only for possession and contraction. Watch me find and fix the errors.",example:`✗ "We have three cat's and two dog's." → ✓ "We have three cats and two dogs."`,demonstration:`"Cat's" — is the cat possessing something? No. Is it a contraction? No. So no apostrophe! "Dog's" — same test, same result. The simple rule: to make a word plural, just add -s or -es. Never add an apostrophe.`,tip:"Before adding an apostrophe, ask: is this possession or contraction? If neither — no apostrophe."},{title:"We Do — Find and Remove",instruction:"Remove every incorrect apostrophe from this passage.",sentences:["At the market we bought apple's, pear's, and two kind's of cheese. The stall's were busy all morning and the seller's were friendly. By noon, all the basket's were empty."],prompt:"Which apostrophes are wrong? How do you know? What test did you apply?"},{title:"You Do — Your Turn",instruction:"Rewrite each sentence, correcting all apostrophe errors. Some sentences may have no error.",tasks:["The team's jerseys were hanging on hook's in the changing room.","Both runner's crossed the line within second's of each other.","The children's laughter echoed across the playground.","Three dog's barked at the cat's on the fence.","✦ Bonus: Write 5 sentences that correctly use apostrophes for possession, contraction, and plural — making sure plurals never have apostrophes."]},[{code:"Writing — Punctuation (Knowledge)",label:"Apostrophes: not for plurals",detail:`NZC Phase 2 Writing — Punctuation (Knowledge): "Apostrophes are used to show possession and to mark omitted letters in contractions. They are never used to form plurals. The 'greengrocer's apostrophe' (apple's, pear's) is one of the most common punctuation errors in English." Students develop the two-question test: Is this possession? Is this a contraction? If neither — no apostrophe.`},{code:"Writing — Writing Process (Practice)",label:"Editing for apostrophe errors",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing to check that it makes sense and is accurate, including checking punctuation." This lesson builds a targeted apostrophe audit: applying the possession/contraction test to every apostrophe in a passage and removing those that fail both tests — a practical and reliable editing strategy.'}])},5:{Monday:g("Brackets & dashes for parenthetical information","Writing — Punctuation (Knowledge): brackets and dashes are used to add parenthetical (non-essential) information within a sentence; students choose between them based on the degree of emphasis and formality required.",{title:"I Do — The Aside in a Sentence",instruction:"Sometimes we want to add extra information inside a sentence without breaking its flow. Brackets and dashes both do this job — but with different emphasis. Watch me use both.",example:'Brackets: "The tūī (a native honeyeater) feeds on kōwhai nectar." | Dashes: "The tūī — our boldest garden visitor — feeds on kōwhai nectar."',demonstration:"Brackets add a quiet aside — the reader can almost skip it. Dashes shout for attention — they make the parenthetical feel dramatic or important. Use brackets for factual clarifications. Use dashes when you want the reader to pause and notice.",tip:"Remove the parenthetical — does the sentence still make sense? Good — it's truly parenthetical. Now choose: quiet (brackets) or dramatic (dashes)?"},{title:"We Do — Choose the Right Mark",instruction:"For each sentence, decide whether brackets or dashes are more appropriate. Add them correctly.",sentences:["The pōhutukawa also called the New Zealand Christmas tree blooms in December.","The final score 14 to 12 in our favour was the best result of the season.","Captain Cook who arrived in 1769 was the first European to chart New Zealand's coastline."],prompt:"Is this extra information quiet and factual, or dramatic and emphatic? That decides the mark."},{title:"You Do — Your Turn",instruction:"Add brackets or dashes to each sentence. Write a reason for your choice.",tasks:["The Whanganui River legally recognised as a person in 2017 is sacred to the Māori people.","My brother the one who never reads finished the whole novel in a weekend.","Mount Taranaki also known as Egmont is one of New Zealand's most symmetrical volcanoes.","✦ Bonus: Write 4 sentences of your own — two using brackets and two using dashes. Make sure the parenthetical is genuinely non-essential in each."]},[{code:"Writing — Punctuation (Knowledge)",label:"Brackets & dashes for parentheticals",detail:'NZC Phase 2 Writing — Punctuation (Knowledge): "Brackets and dashes are used to add parenthetical (non-essential) information within a sentence. Brackets indicate quiet, factual asides; dashes create emphasis and draw attention to the additional information. Both marks come in pairs, and the sentence must make grammatical sense if the parenthetical is removed." This is an explicitly expected Phase 2 punctuation skill.'},{code:"Writing — Punctuation (Practice)",label:"Using parenthetical punctuation for effect",detail:`NZC Phase 2 Writing — Punctuation (Practice): Students are expected to "use a range of punctuation accurately and for effect." Choosing between brackets and dashes is a purposeful punctuation decision — not a random one. This lesson teaches students that punctuation shapes the reader's experience of additional information: brackets whisper, dashes shout. That awareness is the foundation of punctuation as a craft tool.`}]),Tuesday:g("Comparative & superlative adjectives","Writing — Sentence Structure (Knowledge): comparative adjectives compare two things; superlative adjectives compare three or more; students apply the rules for regular and irregular forms accurately.",{title:"I Do — More, Most, -er, -est",instruction:"Comparative adjectives compare two things. Superlative adjectives compare three or more. Short adjectives add -er/-est; longer adjectives use more/most; some are irregular.",example:"fast → faster → fastest | beautiful → more beautiful → most beautiful | good → better → best",demonstration:'Rule: 1–2 syllable adjectives → -er/-est: tall/taller/tallest. 3+ syllable adjectives → more/most: exciting/more exciting/most exciting. Exceptions: good/better/best, bad/worse/worst, far/further/furthest. Test: if "-er" sounds natural — use it.',tip:'Try adding -er: if it sounds natural, use it. If it sounds awkward ("intelligenter?"), use "more."'},{title:"We Do — Form the Comparatives",instruction:"Form the comparative and superlative of each adjective and use each in a sentence.",sentences:["cold → ___ → ___","dangerous → ___ → ___","good → ___ → ___"],prompt:"Which rule applies? Are there any exceptions here? Can you use each in an example sentence?"},{title:"You Do — Your Turn",instruction:"Complete the comparison chart and write sentences using the correct form.",tasks:['happy → ___ → ___  |  Use "happiest" in a sentence.','mysterious → ___ → ___  |  Use "more mysterious" in a sentence.','bad → ___ → ___  |  Use "worst" in a sentence.',"✦ Bonus: Write a paragraph comparing two animals, using at least four comparative or superlative adjectives."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"Comparative & superlative adjectives",detail:`NZC Phase 2 Writing — Sentence Structure (Knowledge): "Adjectives can be modified to express degrees of comparison. Comparative forms (using -er or 'more') compare two things; superlative forms (using -est or 'most') compare three or more. Some adjectives have irregular comparative and superlative forms (good/better/best, bad/worse/worst)." Students learn and apply both the rules and the exceptions.`},{code:"Writing — Vocabulary (Practice)",label:"Precise comparative language",detail:'NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases… that are fit for purpose and audience." Using precise comparative and superlative forms — rather than vague modifiers ("more good," "more bad") — is a key marker of vocabulary accuracy at Years 5–6. This lesson also reinforces that form choice follows a rule, not guesswork.'}]),Wednesday:g("Combining short sentences for variety","Writing — Sentence Structure (Practice): students combine multiple short sentences into smoother compound and complex sentences, eliminating choppiness and creating better flow.",{title:"I Do — Stitch the Choppy Sentences",instruction:"Too many short sentences in a row creates choppy, monotonous writing. Watch me combine short sentences into longer, smoother ones using conjunctions, relative clauses, and participial phrases.",example:'Choppy: "The kererū landed. It ate the berries. It flew away. It was very fast." → Smooth: "The kererū landed, ate the berries, and flew away with surprising speed."',demonstration:'I combined four sentences into one by removing repeated subjects and joining the actions with commas and "and." I also replaced "very fast" with "surprising speed" — more precise and vivid. The rhythm is now smooth rather than clipped.',tip:"If three or more sentences in a row are short and start with the same subject — they can probably be combined."},{title:"We Do — Combine Together",instruction:"Combine each group of short sentences into one or two smooth sentences.",sentences:["The storm arrived quickly. The wind was strong. Trees bent. Branches snapped.","She practised every day. She was nervous. The performance was coming soon."],prompt:"Which sentences share a subject and can be combined? Which conjunction or relative clause best links the ideas?"},{title:"You Do — Your Turn",instruction:"Combine each group into one well-constructed sentence.",tasks:["The kaiako walked in. She smiled. She placed a pile of books on the desk. She waited.","The volcano was silent. It had been silent for years. Scientists were watching it. They were worried.","The dog sat by the door. It was whining. It wanted to go outside. It had been waiting for an hour.","✦ Bonus: Find a paragraph in your own writing that has more than three consecutive short sentences. Combine at least two pairs."]},[{code:"Writing — Sentence Structure (Practice)",label:"Combining sentences for flow",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write a variety of sentence structures for effect and clarity," including combining short sentences to improve rhythm and flow. Eliminating choppy repetition by merging sentences with conjunctions, relative clauses, and shared verb phrases is a key revision skill at Years 5–6 — it shows control over sentence construction, not just sentence production.'},{code:"Writing — Writing Process (Practice)",label:"Revising for sentence variety",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing… making changes to vocabulary, punctuation, and structure to improve clarity and impact." This lesson practises a specific revision strategy: identifying runs of short sentences, diagnosing why they feel choppy, and selecting the best combining method — conjunction, relative clause, or shared verb chain.'}]),Thursday:g("Peer editing: punctuation variety","Writing — Writing Process (Practice): students apply a punctuation variety checklist to their own and a partner's writing, giving and receiving specific feedback on comma, colon, semicolon, and dash use.",{title:"I Do — Reading for Punctuation Variety",instruction:"Today I'm going to show you how to read a piece of writing specifically to assess its punctuation variety — not just accuracy.",example:"Checklist: ☐ At least one comma after a fronted adverbial ☐ At least one colon ☐ At least one semicolon ☐ At least one pair of brackets or dashes ☐ No comma splices",demonstration:`I read the passage once for meaning. Then I read again specifically for punctuation. I mark each type I find. I notice what's missing. Then I give specific feedback: "You've used commas well in lists, but there are no semicolons — try joining two of these related sentences with one."`,tip:'Specific feedback is helpful. "Your punctuation is good" is not. "You need a comma after your fronted adverbial on line 2" is.'},{title:"We Do — Punctuation Variety Audit",instruction:"Let's audit this passage together for punctuation variety.",sentences:["The science fair was held on Thursday. Every class had an entry. Our class made a working volcano. It erupted three times. The judges were impressed. We won first place. It was a good day."],prompt:"Where could a semicolon replace a full stop? Where could a dash add drama? Is there a list that needs a colon?"},{title:"You Do — Your Turn",instruction:"Swap a piece of your writing with a partner. Edit each other's work for punctuation variety using the checklist.",tasks:["✦ Checklist: At least one semicolon used correctly.","✦ Checklist: At least one colon introducing a list or explanation.","✦ Checklist: At least one dash or pair of brackets for parenthetical information.","✦ Bonus: Rewrite your partner's weakest paragraph — the one with the least punctuation variety — as a model of what it could look like."]},[{code:"Writing — Writing Process (Practice)",label:"Peer editing for punctuation variety",detail:`NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "share writing with others and respond to feedback to improve their work." Peer editing for punctuation variety is a specific application of this expectation — students give targeted, rule-based feedback (not just "it's good") and practise reading writing through an editor's eye rather than a writer's eye.`},{code:"Writing — Punctuation (Practice)",label:"Applying a punctuation checklist",detail:'NZC Phase 2 Writing — Punctuation (Practice): Students are expected to "use a range of punctuation accurately and for effect." This lesson consolidates all Term 2 punctuation learning — commas after fronted adverbials, colons, semicolons, brackets, and dashes — in a peer editing context where students must both recognise correct use and explain the rule behind each mark.'}])},6:{Monday:g("Greek & Latin roots in everyday words","Writing — Vocabulary (Knowledge): many English words are built from Greek and Latin roots; understanding common roots enables students to decode unfamiliar words and expand their vocabulary systematically.",{title:"I Do — Crack the Code",instruction:"Many English words are built from Greek and Latin roots. Once you know a root, you can work out the meaning of dozens of words you've never seen before.",example:'"tele" (far) → telescope, television, telepathy | "aqua" (water) → aquatic, aquarium, aqueduct | "bio" (life) → biology, biography, biodiversity',demonstration:'If you see "submarine," you might not know it — but "sub" means under and "marine" means sea. So submarine = under the sea. Same with "microphone" — "micro" (small) + "phone" (sound) = small sound amplifier. Roots unlock words like a key.',tip:"When you hit an unknown word, look for a root you recognise. Even a partial match gives you a clue."},{title:"We Do — Decode Together",instruction:"Use the roots provided to work out what each word means. Then check by looking at the context sentence.",sentences:['"geo" (earth): geology, geography, geothermal — what does "geothermal" likely mean?','"script/scribe" (write): manuscript, inscription, transcribe — what does "transcribe" likely mean?','"spec/spect" (look/see): inspect, spectator, spectacular — what does "spectator" likely mean?'],prompt:"Can you find other words that share these roots? How does knowing the root help you read unfamiliar texts?"},{title:"You Do — Your Turn",instruction:"Use your knowledge of roots to answer each question.",tasks:['The root "port" means carry. What do these words mean: export, import, transport, portfolio?','The root "vis/vid" means see. Use it to work out: visible, invisible, vision, evidence.','The root "terra" means land/earth. What do: terrain, territory, terrarium, extraterrestrial mean?',"✦ Bonus: Find 5 words in a book, magazine, or website that share a Greek or Latin root. List the root, its meaning, and the words that use it."]},[{code:"Writing — Vocabulary (Knowledge)",label:"Greek & Latin roots",detail:'NZC Phase 2 Writing — Vocabulary (Knowledge): "Many English words are built from Latin and Greek roots, prefixes, and suffixes. Understanding the meaning of word parts enables students to work out the meaning of unfamiliar words and to build their vocabulary systematically." This lesson develops morphological awareness — knowing that "geo" means earth unlocks geology, geography, geothermal, and geocentric simultaneously.'},{code:"Writing — Vocabulary (Practice)",label:"Using root knowledge in writing",detail:'NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "use knowledge of word origins, roots, and word families to extend vocabulary." Understanding that "port" means carry (import, export, transport) gives students a transferable tool — they can both decode unfamiliar words when reading and select more precise vocabulary when writing.'}]),Tuesday:g("Adverbial phrases for time & manner","Writing — Sentence Structure (Practice): adverbial phrases extend single adverbs by adding precision and texture; students replace weak single adverbs with richer adverbial phrases that tell the reader more.",{title:"I Do — Beyond Single Adverbs",instruction:"A single adverb tells us how or when. An adverbial PHRASE does the same job but with more precision and colour.",example:'"She spoke quietly." → "She spoke <u>in a hushed, urgent whisper</u>." | "He left quickly." → "He left <u>before anyone could ask questions</u>."',demonstration:'"Quietly" tells us the manner. "In a hushed, urgent whisper" tells us manner AND gives texture — we can picture it. "Before anyone could ask questions" tells us time AND hints at motivation. Adverbial phrases carry more weight than single adverbs.',tip:"Spot a lone adverb. Ask: can I replace it with a phrase that tells the reader more? If yes — upgrade it."},{title:"We Do — Upgrade Together",instruction:"Replace each underlined adverb with an adverbial phrase that adds more information.",sentences:["The tūī sang <u>loudly</u> in the pōhutukawa.","The tamariki waited <u>nervously</u> for the results.","The boat left <u>early</u>."],prompt:"What kind of adverbial phrase fits — one of manner, time, or place? Can you add detail and stay true to the context?"},{title:"You Do — Your Turn",instruction:"Rewrite each sentence by replacing the adverb in brackets with a precise adverbial phrase.",tasks:["The kaitiaki worked [hard] to restore the wetland.","The team celebrated [happily] after the final whistle.","She finished her speech [suddenly].","✦ Bonus: Write a paragraph of 5 sentences about an event or journey. Use at least three different adverbial phrases — one of time, one of manner, one of place."]},[{code:"Writing — Sentence Structure (Practice)",label:"Adverbial phrases for precision",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "expand sentences by adding adverbial and prepositional phrases to express location, time, and manner." This lesson advances from single adverbs to adverbial phrases — teaching students that a phrase ("in a hushed, urgent whisper") carries more information and creates a richer picture than a single word ("quietly") ever can.'},{code:"Writing — Vocabulary (Practice)",label:"Replacing weak adverbs with phrases",detail:`NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases… that are fit for purpose and audience." Replacing a generic adverb with a specific adverbial phrase is a key vocabulary refinement skill at Phase 2 — it demonstrates that the student is thinking about the reader's experience and choosing language that creates a precise and vivid picture.`}]),Wednesday:g("Who/where/when phrases in persuasive writing","Writing — Composing (Practice): specific who, where, and when details make persuasive arguments more credible and harder to dismiss; students embed precise detail in persuasive sentences and paragraphs.",{title:"I Do — Detail That Persuades",instruction:"In Term 1 we used who/where/when phrases to add descriptive detail. This week we use the same technique in persuasive writing — where specific detail makes arguments more convincing.",example:'Vague: "Schools should have gardens." → Specific: "Schools across Aotearoa, from urban Auckland to rural Northland, should have gardens where students can grow and harvest their own kai."',demonstration:'The added phrases — "across Aotearoa, from urban Auckland to rural Northland" (where) and "where students can grow and harvest their own kai" (who/what) — make the claim feel specific and grounded. Vague arguments are easy to dismiss. Specific ones are harder to ignore.',tip:"In persuasion, specific detail builds credibility. WHO would benefit? WHERE would this happen? WHEN should it change? Answer those questions inside your sentences."},{title:"We Do — Make It Specific",instruction:"Add who, where, or when detail to each persuasive sentence to make it more convincing.",sentences:["Students should have access to nature.","Communities need to protect waterways.","Young people deserve to have their voices heard."],prompt:"Which type of detail makes each argument stronger — who, where, or when? Can you add more than one?"},{title:"You Do — Your Turn",instruction:"Expand each bare persuasive claim using who/where/when phrases.",tasks:['Claim: "Aotearoa needs more native tree planting." Add a where and a when phrase.','Claim: "Students learn better outdoors." Add a who and a where phrase.','Claim: "Schools should start later." Add a who and a when phrase.',"✦ Bonus: Write a persuasive paragraph (5–6 sentences) on a topic you care about. Every sentence must include at least one who, where, or when detail."]},[{code:"Writing — Composing (Practice)",label:"Specific detail in persuasion",detail:'NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader" and to "provide specific, concrete detail that supports the purpose." In persuasive writing, specificity is a core argument strategy — claims supported by precise who, where, and when details are more credible and more resistant to dismissal than vague generalisations.'},{code:"Writing — Text Structure (Practice)",label:"Building convincing persuasive paragraphs",detail:'NZC Phase 2 Writing — Text Structure (Practice): Students are expected to "organise ideas into paragraphs with a clear main idea, supported by relevant detail" in persuasive writing. This lesson directly builds the ability to support a persuasive topic sentence with specific, embedded detail — the who, where, and when that transforms a claim into a convincing argument.'}]),Thursday:g("Editing: replacing overused words ('nice', 'good')","Writing — Vocabulary (Practice) & Writing Process (Practice): students identify and replace the most overused and vague words in their writing with precise, purposeful alternatives.",{title:"I Do — The Vague Word Hit List",instruction:"Some words appear in almost every piece of student writing: nice, good, bad, big, little, went, got, said, things, stuff. They're not wrong — they're just empty. Watch me hunt them down and replace them.",example:'"It was a nice day and we had a good time doing lots of fun things." → "The sun blazed over the harbour and we spent the afternoon kayaking, laughing until our arms gave out."',demonstration:'"Nice day" → specific weather detail. "Good time" → specific activity. "Lots of fun things" → actual examples. The second version creates a picture. The first creates nothing.',tip:"The vague word hit list: nice, good, bad, big, little, went, got, said, things, stuff, very, really. Highlight every one. Each is an upgrade opportunity."},{title:"We Do — Upgrade Together",instruction:"Find every vague word in this passage and replace it with something precise.",sentences:["We went to the nice beach and it was really good. We did lots of fun things and got really tired. The food was nice and everyone said it was a good day."],prompt:"How many vague words can you find? What specific, precise word or phrase could replace each one?"},{title:"You Do — Your Turn",instruction:"Rewrite each sentence, replacing every vague word with a precise alternative.",tasks:["The movie was really good and the things that happened were very exciting.","She is a nice person who always says good things to people.","It was a bad situation and lots of bad things went wrong.","✦ Bonus: Take a paragraph from your own writing. Highlight every word from the vague word hit list. Rewrite the paragraph with every vague word upgraded."]},[{code:"Writing — Vocabulary (Practice)",label:"Replacing vague words",detail:'NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases… that are fit for purpose and audience" and to "consider the effect of word choice on the reader." This lesson targets the most pervasive vocabulary weakness at Years 5–6 — over-reliance on generic, high-frequency words — and builds the habit of interrogating each word choice against a concrete alternative.'},{code:"Writing — Writing Process (Practice)",label:"Vocabulary audit in revision",detail:`NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing… making changes to vocabulary, punctuation, and structure to improve clarity and impact." The vague word audit — highlighting every word from the hit list and challenging each one — is a practical revision strategy that directly improves the precision and vividness of students' writing at Phase 2.`}])},7:{Monday:g("Colons to introduce lists","Writing — Punctuation (Knowledge): a colon introduces a list only when a complete sentence precedes it; students apply this rule accurately and correct common misuses of the colon.",{title:"I Do — The Colon That Sets Up a List",instruction:"We met colons in Term 1. This week we focus specifically on using them to introduce lists — and on the rule about what must come BEFORE the colon.",example:'✓ "The kete contained three items: a tī kōuka leaf, a piece of bone, and a carved pounamu." | ✗ "The kete contained: a tī kōuka leaf, a piece of bone, and a carved pounamu."',demonstration:'The colon introduces the list — but only when a complete sentence comes before it. "The kete contained three items" is a complete sentence ✓. "The kete contained" is NOT a complete sentence ✗ — so no colon. The rule: a complete sentence must precede the colon.',tip:"Before the colon = a complete sentence. After the colon = the list. Test: can the part before the colon stand alone? If not — remove the colon."},{title:"We Do — Fix or Confirm",instruction:"Decide whether the colon is used correctly in each sentence. Fix those that aren't.",sentences:["The scientist needed: a microscope, slides, and a sample jar.","The rescue team brought the following equipment: ropes, a first-aid kit, and torches.","To make rewena bread you will need: flour, potato water, sugar, and salt."],prompt:"Is the part before the colon a complete sentence? If not, what needs to change?"},{title:"You Do — Your Turn",instruction:"Add a colon in the correct place, or rewrite so the colon is used correctly.",tasks:["The pā required three things to defend effectively high ground, a clear view, and strong palisades.","There are many native birds in the Waikato region including: tūī, kererū, and pīwakawaka.","She packed everything she would need for the tramp: food, a sleeping bag, a compass, and wet-weather gear.","✦ Bonus: Write five sentences, each using a colon to introduce a list. Make sure every sentence before the colon is grammatically complete."]},[{code:"Writing — Punctuation (Knowledge)",label:"Colons before lists",detail:`NZC Phase 2 Writing — Punctuation (Knowledge): "A colon is used after a complete clause to introduce a list, explanation, or quotation. A common error is placing a colon after an incomplete clause (e.g. 'The bag contained:') — the part before the colon must be a grammatically complete sentence." Students learn to test for completeness before adding a colon, developing both accuracy and understanding of clause structure.`},{code:"Writing — Punctuation (Practice)",label:"Applying colons accurately",detail:'NZC Phase 2 Writing — Punctuation (Practice): Students are expected to "use a range of punctuation accurately and for effect," including colons. This lesson develops the completeness test as a reliable self-checking strategy — students identify whether the part before the colon could stand alone as a sentence before applying the mark, preventing the most common colon error at Years 5–6.'}]),Tuesday:g("Progressive tenses: past & present continuous","Writing — Sentence Structure (Knowledge): past and present progressive tenses express ongoing actions; students form and use these tenses accurately, understanding how past progressive sets a background scene interrupted by simple past events.",{title:"I Do — Actions in Progress",instruction:"The progressive (or continuous) tense shows an action that was happening over a period of time — not just a single completed event.",example:'Present progressive: "The kākāpō <u>is climbing</u> the tree right now." | Past progressive: "The kākāpō <u>was climbing</u> when we first spotted it."',demonstration:'Present progressive = is/are + verb-ing: "She is writing." Past progressive = was/were + verb-ing: "She was writing when the bell rang." Key use: past progressive sets a scene that another action interrupts. "He was reading when the power cut out."',tip:'Past progressive sets the background scene. Simple past is the event that interrupts it. Together: "She was sleeping when the earthquake struck."'},{title:"We Do — Form and Use",instruction:"Complete each sentence with the correct progressive form.",sentences:["The students ___ (prepare) their speeches when the fire alarm went off.","Look out the window — the kererū ___ (eat) all the berries!","While the waka ___ (cross) the harbour, the wind suddenly changed direction."],prompt:"Is this happening right now (present) or was it in progress at a past moment (past)? That decides was/were vs is/are."},{title:"You Do — Your Turn",instruction:"Write sentences using the progressive tense as directed.",tasks:["Write a sentence using past progressive to set a scene, then use simple past for an interrupting event.","Describe what three different people are doing right now using present progressive.",'Rewrite in past progressive: "The rangatira spoke to the crowd. The sun set behind the hills."',"✦ Bonus: Write a short recount (5 sentences) of a real or imagined event. Use past progressive at least twice to set the scene before key moments."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"Progressive tenses",detail:`NZC Phase 2 Writing — Sentence Structure (Knowledge): "The present progressive tense (is/are + verb-ing) describes an action happening at the moment of speaking. The past progressive tense (was/were + verb-ing) describes an action that was in progress at a past moment, often interrupted by another event in simple past. Both forms require the auxiliary verb 'be' and the present participle (-ing form)."`},{code:"Writing — Sentence Structure (Practice)",label:"Using progressive tense for narrative effect",detail:`NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write grammatically correct sentences using a range of tenses." In narrative writing, past progressive is particularly powerful for scene-setting — it creates a sustained background action ("The village was sleeping") that simple past then disrupts ("when the alarm sounded"). This lesson develops students' control of tense as a narrative craft tool.`}]),Wednesday:g("Complex sentences using 'although', 'unless', 'while'","Writing — Sentence Structure (Knowledge & Practice): 'although', 'unless', and 'while' are subordinating conjunctions that express contrast, condition, and simultaneity; students use them accurately to create nuanced complex sentences.",{title:"I Do — Conjunctions That Add Nuance",instruction:'"Although," "unless," and "while" are subordinating conjunctions that add nuance — they create contrast, condition, and simultaneous action.',example:'"<u>Although</u> it was raining, the match continued." | "The match will continue <u>unless</u> there is lightning." | "<u>While</u> the rain fell, the players kept their positions."',demonstration:`"Although" = contrast (it happened despite something). "Unless" = condition (this won't happen IF something else does). "While" = at the same time. Each creates a different relationship — choosing the right conjunction is part of a writer's craft.`,tip:'"Although" = despite this. "Unless" = except if. "While" = at the same time as. Choose based on the relationship between your two ideas.'},{title:"We Do — Choose the Right Conjunction",instruction:"Complete each sentence with although, unless, or while.",sentences:["___ the journey was exhausting, Mere never once complained.","The kaiako won't begin ___ everyone is seated and listening.","___ the kettle boiled, she set out the cups and the tea."],prompt:"What relationship exists between the two clauses — contrast, condition, or simultaneity?"},{title:"You Do — Your Turn",instruction:"Write two sentences for each conjunction — one with the subordinate clause first, one with it second.",tasks:["although (contrast)","unless (condition)","while (simultaneous)","✦ Bonus: Write a paragraph of 6 sentences about a challenge or difficult situation. Use although, unless, and while at least once each."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"Subordinating conjunctions: although, unless, while",detail:`NZC Phase 2 Writing — Sentence Structure (Knowledge): "'Although' expresses contrast (despite the subordinate clause, the main clause is still true); 'unless' expresses condition (the main clause won't happen except under the stated condition); 'while' expresses simultaneity (both actions happen at the same time). Each conjunction creates a different logical relationship between the clauses — understanding these distinctions is a key Phase 2 grammar expectation."`},{code:"Writing — Sentence Structure (Practice)",label:"Complex sentences for nuance",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write a variety of sentence structures — including complex sentences — for effect and clarity." This lesson extends complex sentence use to three conjunctions that require genuine understanding of logical relationships: contrast, condition, and simultaneity — moving students beyond the familiar "because" and "when" into more nuanced subordination.'}]),Thursday:g("Editing: checking tense consistency","Writing — Writing Process (Practice) & Sentence Structure (Knowledge): students apply a systematic verb audit to identify and correct tense inconsistencies in modelled and their own writing.",{title:"I Do — The Verb Audit",instruction:"A tense audit means underlining every verb in a passage, labelling it as past or present, and then correcting any that break the pattern.",example:'"The explorer sets out at dawn. She walked for three hours before she reaches the ridge." — sets (Pr), walked (P), reaches (Pr).',demonstration:'Two present, one past — inconsistent. I decide: past tense works better for a recount. Fix: "The explorer set out at dawn. She walked for three hours before she reached the ridge." — all past, all consistent.',tip:'Be especially careful with "was/is" and "said/says" — these are the most common accidental tense switches.'},{title:"We Do — Audit Together",instruction:"Underline every verb, label each P (past) or Pr (present), then rewrite in consistent past tense.",sentences:["The market is busy on Saturday mornings. Stalls lined both sides of the street. Vendors called out their prices. The smell of fresh bread drifts through the air. Families stopped to chat and children run between the stalls."],prompt:"Which verbs switch tense? What is the dominant tense here? Rewrite consistently."},{title:"You Do — Your Turn",instruction:"Underline all verbs, label each one P or Pr, then rewrite in consistent past tense.",tasks:["The diver slips below the surface. The water was cold and very clear. She searches for the wreck that locals told her about. After ten minutes, she spots a shadow on the seabed. She swam closer and felt her heart race.","✦ Bonus: Take a piece of your own writing and do a full tense audit on it. Note how many switches you find."]},[{code:"Writing — Writing Process (Practice)",label:"Tense audit as revision strategy",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing to check that it makes sense and is accurate." The tense audit — underline every verb, label the tense, decide on consistency, fix mismatches — is a specific, repeatable revision strategy that goes beyond casual re-reading. It is a direct application of the Phase 2 expectation that students revise systematically.'},{code:"Writing — Sentence Structure (Knowledge)",label:"Identifying tense in context",detail:`NZC Phase 2 Writing — Sentence Structure (Knowledge): "Verbs carry tense and must remain consistent throughout a piece of writing. Tense shifts disrupt the reader's experience and signal a lack of control over the writing." This editing lesson deepens grammatical knowledge by requiring students to identify and label verb tense in context before applying corrections — connecting knowledge to practice.`}])},8:{Monday:g("Spelling: tricky high-frequency words","Writing — Conventions (Knowledge): certain high-frequency words have irregular or non-phonetic spellings that must be learned; students apply strategies to memorise and recall these words accurately.",{title:"I Do — Words That Break the Rules",instruction:"Some high-frequency words don't follow phonetic patterns — they must be memorised. Watch me demonstrate three strategies for locking these tricky spellings in.",example:"receive, separate, necessary, occurrence, privilege, conscience, rhythm, liaison",demonstration:`Strategy 1 — Look, Cover, Write, Check: study the word, cover it, write it from memory, check. Strategy 2 — Find the word within the word: "sep-a-rate" (not sep-er-ate) — there's "a rat" in separate! Strategy 3 — Mnemonic: "Rhythm Helps Your Two Hips Move" — first letters spell RHYTHM.`,tip:"When you spell a word wrong twice, look for a mnemonic or pattern that makes the correct spelling stick."},{title:"We Do — Spelling Strategies",instruction:"Use at least one strategy to help you learn each of these tricky spellings.",sentences:["necessary (one c, two s) — find a mnemonic.","occasion (two c, one s) — find the pattern.",'definitely (not "definately") — break it into parts.'],prompt:"Which strategy worked best for each word? Can you teach your strategy to a partner?"},{title:"You Do — Your Turn",instruction:"Use Look, Cover, Write, Check for each word. Then write a sentence using each one correctly.",tasks:["accommodate (two c, two m)","embarrass (two r, two s)","government (silent n before m)",'privilege (not "priviledge")',"✦ Bonus: Create a personal spelling list of 5 words you consistently misspell. Apply one strategy to each and test yourself tomorrow."]},[{code:"Writing — Conventions (Knowledge)",label:"Tricky high-frequency spellings",detail:'NZC Phase 2 Writing — Conventions (Knowledge): "Some high-frequency words have irregular or non-phonetic spellings that must be memorised through repeated practice and strategic learning. Students develop spelling knowledge through a range of strategies including visual memory (Look, Cover, Write, Check), morphological analysis (breaking into meaningful parts), and mnemonics." Accurate spelling of high-frequency words is a core expectation at Years 5–6.'},{code:"Writing — Writing Process (Practice)",label:"Checking and correcting spelling",detail:`NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing to check that it makes sense and is accurate, including checking spelling." This lesson builds students' metacognitive awareness of their own spelling weaknesses and gives them a toolkit of strategies — rather than relying on spellcheck — for identifying and fixing errors in their writing.`}]),Tuesday:g("Prepositions of direction & movement","Writing — Sentence Structure (Knowledge): directional prepositions express movement through, across, towards, and along specific paths; students use them precisely to create clear, vivid spatial descriptions.",{title:"I Do — Which Way? Prepositions of Direction",instruction:"Some prepositions express static location (in, on, under). Others express direction and movement — they tell us where something is going. Watch me use directional prepositions to make movement vivid.",example:'"The waka moved <u>across</u> the harbour, <u>through</u> the channel, and <u>towards</u> the shore."',demonstration:'"Across" — movement over a surface from one side to another. "Through" — movement from one side of something to the other by passing inside it. "Towards" — movement in the direction of something. "Along" — movement following the length of something. Each is precise about the geometry of the movement.',tip:"Visualise the movement and ask: is it over a surface (across), inside something (through), in a direction (towards), or following a line (along)?"},{title:"We Do — Choose the Right Preposition",instruction:"Choose the most accurate directional preposition for each gap.",sentences:["The children ran ___ (across/through/along) the beach to the water's edge.","The tuna moved ___ (across/through/towards) the dark water of the river.","She walked ___ (along/towards/through) the ridge, keeping the sea in sight."],prompt:"Picture the movement precisely. Which preposition describes the path most accurately?"},{title:"You Do — Your Turn",instruction:"Add the correct directional preposition and then rewrite the sentence with more specific detail.",tasks:["The kererū flew ___ the canopy and ___ the clearing.","The river flows ___ the gorge and ___ the sea.","She moved ___ the crowd and ___ the stage.","✦ Bonus: Write a paragraph of 5 sentences describing a journey — by foot, waka, or bike. Use at least four different directional prepositions precisely."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"Directional prepositions",detail:'NZC Phase 2 Writing — Sentence Structure (Knowledge): "Prepositions of direction (across, through, towards, along, past, into, out of) express movement in relation to a surface, an interior, or a destination. Choosing the correct directional preposition requires visualising the geometry of the movement — is it over a surface, inside something, towards a target, or along a path?" Students learn to distinguish between similar prepositions by thinking spatially.'},{code:"Writing — Sentence Structure (Practice)",label:"Precise spatial writing",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "expand sentences by adding prepositional phrases to express location" and direction. Using directional prepositions precisely — rather than vague alternatives ("went near," "moved by") — is a key skill in descriptive and narrative writing at Phase 2, enabling students to place the reader inside the movement they are describing.'}]),Wednesday:g("Making vague sentences specific","Writing — Composing (Practice) & Vocabulary (Practice): students transform vague, general sentences into specific, detailed ones by adding precise nouns, verbs, and modifiers that answer the reader's implicit questions.",{title:"I Do — Vague vs. Specific",instruction:"Vague sentences tell the reader almost nothing. Specific sentences give them something to picture. Watch me transform a vague sentence into a specific one by answering the reader's questions.",example:'Vague: "A bird made a sound in the tree." → Specific: "A tūī burst into a cascading trill from the topmost branch of the pōhutukawa."',demonstration:"Reader's questions: WHAT bird? → tūī. WHAT sound? → cascading trill. WHERE in the tree? → topmost branch. WHAT tree? → pōhutukawa. Answering each question turns a generic sentence into one that only this moment could have produced.",tip:"For every noun, ask: what exactly? For every verb, ask: how exactly? For every place, ask: where exactly?"},{title:"We Do — Make It Specific",instruction:"Rewrite each vague sentence by answering every implied reader question.",sentences:["A person walked past.","The weather changed.","Something fell."],prompt:"What are the reader's questions for each sentence? What specific detail answers each one?"},{title:"You Do — Your Turn",instruction:"Transform each vague sentence into a specific one. Aim for a sentence only THIS moment could produce.",tasks:["A vehicle went by.","The animal made a noise.","She did something with the object.","The food smelled good.","✦ Bonus: Write 4 intentionally vague sentences, then rewrite each one with maximum specificity. Compare the two versions."]},[{code:"Writing — Composing (Practice)",label:"Creating specific, vivid writing",detail:`NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader," including providing specific, concrete detail that allows the reader to visualise the scene. This lesson teaches the "reader's question" technique — systematically asking 'what exactly? how exactly? where exactly?' to identify and fill gaps that leave writing vague and generic.`},{code:"Writing — Vocabulary (Practice)",label:"Precise nouns and verbs",detail:'NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases… that are fit for purpose and audience," choosing Tier 2 vocabulary that is precise and cross-curricular. Replacing generic nouns ("bird") with specific ones ("tūī") and generic verbs ("made a sound") with precise ones ("burst into a cascading trill") is the most direct application of this principle — specificity IS vocabulary.'}]),Thursday:g("Editing: strengthening narrative openings","Writing — Writing Process (Practice) & Composing (Practice): students evaluate narrative openings against criteria for engagement and revise weak openings to draw the reader immediately into the story.",{title:"I Do — First Sentences That Work",instruction:"A weak opening loses the reader before the story begins. Watch me evaluate three narrative openings against criteria, then revise the weakest one.",example:'Weak: "My name is Jake and this is a story about something that happened to me last summer." | Strong: "The day I found the box, I almost walked straight past it."',demonstration:`The weak opening: tells rather than shows, introduces the narrator self-consciously, contains no tension or mystery. The strong opening: drops us into a specific moment, creates immediate curiosity ("what was in the box?"), and doesn't explain itself. Criteria for a strong opening: specific moment, no explaining, creates a question in the reader's mind.`,tip:"Test: does the opening make the reader ask a question? If not — rewrite until it does."},{title:"We Do — Diagnose and Revise",instruction:"Evaluate each opening against our three criteria. Then revise the weakest one together.",sentences:['"Once upon a time there was a girl who wanted to be an explorer."','"The engine coughed twice, then fell silent. In the distance, the lights of the mainland blinked out."','"I am going to write about the best day I ever had which was when we went to the beach."'],prompt:"Which opening drops you into a specific moment? Which creates a question? Which explains too much?"},{title:"You Do — Your Turn",instruction:"Rewrite each weak opening so it meets all three criteria.",tasks:['"This is the story of how I found out my neighbour was not who she said she was."','"One day something strange happened and I will tell you about it in this story."',`"It was a morning like any other until it wasn't."`,"✦ Bonus: Write three alternative openings for a story of your choice. Choose the best one and explain why."]},[{code:"Writing — Writing Process (Practice)",label:"Evaluating and revising narrative openings",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing… making changes to vocabulary, punctuation, and structure to improve clarity and impact." This lesson applies that revision process to the highest-stakes part of any narrative — the opening sentence. Students evaluate against explicit criteria (specific moment, no explaining, reader question) and revise until the opening works.'},{code:"Writing — Composing (Practice)",label:"Engaging the reader from the first sentence",detail:'NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader." Narrative opening strategy is a key composing skill at Phase 2 — students learn that the most engaging openings drop the reader directly into a specific moment, create immediate curiosity, and resist the urge to explain or introduce the narrator self-consciously.'}])},9:{Monday:g("Alliteration & assonance","Writing — Vocabulary (Knowledge) & Composing (Practice): alliteration (repeated consonant sounds) and assonance (repeated vowel sounds) are sound devices that create rhythm, mood, and texture in writing.",{title:"I Do — Making Writing Sound as Good as It Reads",instruction:"Alliteration repeats the same consonant sound at the start of neighbouring words. Assonance repeats the same vowel sound in the middle of words. Both create rhythm and texture that the reader can hear.",example:'Alliteration: "The <u>s</u>ilent <u>s</u>nake <u>s</u>lipped through the <u>s</u>edge." | Assonance: "The r<u>ai</u>n-sl<u>ai</u>n pl<u>ai</u>n."',demonstration:`Alliteration: the "s" sound creates a hissing, slithering effect — perfect for a snake. Assonance: the "ai" sound gives a slow, mournful quality — good for a grey, flat landscape. Both devices work best when they reinforce the meaning or mood, not when they're forced.`,tip:"Sound devices should serve the meaning. If the reader notices the device more than the content — it's too obvious."},{title:"We Do — Hear the Sound",instruction:"Brainstorm sound words for each setting, then build a sentence using alliteration or assonance.",sentences:["Setting: a beach at high tide","Setting: a forest just after rain","Setting: a crowded school cafeteria"],prompt:"What sounds would you hear? What sounds could you create with alliteration or assonance?"},{title:"You Do — Your Turn",instruction:"Write sentences using the device specified.",tasks:['Write an alliterative sentence about a NZ animal using the "k" sound (kiwi, kererū, kākāpō, kārearea).','Write a sentence about the sea using assonance with the "ō" or "oo" sound.',"Write a description of a storm using both alliteration and assonance in the same sentence.","✦ Bonus: Write a 4-line descriptive poem about a NZ landscape. Use alliteration in at least two lines and assonance in at least one."]},[{code:"Writing — Vocabulary (Knowledge)",label:"Sound devices: alliteration & assonance",detail:'NZC Phase 2 Writing — Vocabulary (Knowledge): "Language devices such as alliteration (repeated consonant sounds) and assonance (repeated vowel sounds) create specific effects for the reader — rhythm, mood, and texture. They are most effective when they reinforce the meaning of the writing rather than being applied for their own sake." Students learn to use sound devices deliberately and discriminatingly, not mechanically.'},{code:"Writing — Composing (Practice)",label:"Using sound devices for effect",detail:`NZC Phase 2 Writing — Composing (Practice): Students are expected to "use language devices to create specific effects and engage the reader." Alliteration and assonance are sound-based composing tools — they work on the reader's ear as well as their mind. This lesson develops the discipline of asking 'what mood am I creating?' before selecting which sound to repeat and how often.`}]),Tuesday:g("Coordinating vs. subordinating conjunctions: review","Writing — Sentence Structure (Knowledge): students consolidate their understanding of coordinating (FANBOYS) and subordinating conjunctions, applying the distinction to build and identify compound and complex sentences accurately.",{title:"I Do — Two Types, Two Jobs",instruction:"We've studied both types of conjunction across Terms 1 and 2. Today we consolidate: coordinating conjunctions join equal clauses; subordinating conjunctions create a main clause and a dependent clause.",example:'Coordinating: "The hīkoi was long, <u>but</u> the marchers kept going." | Subordinating: "The marchers kept going <u>although</u> the hīkoi was exhausting."',demonstration:"FANBOYS (for, and, nor, but, or, yet, so) = coordinating — both sides could stand alone. AAAWWUBBIS (after, although, as, when, while, until, because, before, if, since) = subordinating — the dependent clause leans on the main clause.",tip:"Test: remove the conjunction and split the sentence in two. If both halves make sense alone — coordinating. If one half sounds incomplete — subordinating."},{title:"We Do — Classify and Use",instruction:"Identify whether the underlined conjunction is coordinating or subordinating, then explain how you know.",sentences:["The kaiako waited <u>until</u> the class was completely silent.","The experiment failed, <u>yet</u> the students learnt something important.","<u>Because</u> the tide was out, we could walk across to the island."],prompt:"Could both sides stand alone? What type of relationship does each conjunction create?"},{title:"You Do — Your Turn",instruction:"Write sentences using the conjunction type shown.",tasks:["Write a compound sentence using a coordinating conjunction that shows contrast.","Write a complex sentence using a subordinating conjunction that shows cause.","Write a complex sentence where the subordinate clause comes FIRST (with a comma after it).","✦ Bonus: Write a paragraph of 5 sentences about a place you know well. Use at least two coordinating and two subordinating conjunctions. Label each one."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"Coordinating vs. subordinating conjunctions",detail:'NZC Phase 2 Writing — Sentence Structure (Knowledge): "Coordinating conjunctions (FANBOYS: for, and, nor, but, or, yet, so) join two independent clauses of equal grammatical weight — both sides can stand alone. Subordinating conjunctions (because, although, when, unless, while, until, since, as, before, after, if) introduce a dependent clause that cannot stand alone. Understanding this distinction is essential for building compound and complex sentences accurately."'},{code:"Writing — Sentence Structure (Practice)",label:"Compound & complex sentence consolidation",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write a variety of sentence structures — simple, compound, and complex — for effect and clarity." This review lesson consolidates the distinction between compound sentences (coordinating conjunctions, comma before) and complex sentences (subordinating conjunctions, comma only when fronted) — integrating Term 1 and Term 2 sentence structure learning at Phase 2.'}]),Wednesday:g("Paragraph cohesion: pronouns as linking devices",'Writing — Text Structure (Practice): students use personal pronouns, demonstrative pronouns ("this," "these"), and pronoun reference to create cohesion within paragraphs, linking sentences into a connected whole.',{title:"I Do — Pronouns That Hold a Paragraph Together",instruction:'We used connective words in Term 1. This week, we focus specifically on pronouns as cohesive devices — how "he," "she," "they," "it," "this," and "these" reach back to a previous sentence and pull ideas together.',example:`"The tuatara is one of New Zealand's most ancient reptiles. <u>It</u> has barely changed in 200 million years. <u>This</u> makes <u>it</u> a living link to the age of the dinosaurs."`,demonstration:'"It" in sentence 2 refers back to "tuatara" — no need to repeat the noun. "This" in sentence 3 refers back to the whole idea of sentence 2. Each pronoun acts like a thread, stitching sentences into a paragraph rather than a list.',tip:"After writing a paragraph, draw an arrow from each pronoun to what it refers to. Every pronoun should have a clear, unambiguous referent."},{title:"We Do — Stitch It Together",instruction:"Replace the repeated nouns with appropriate pronouns to improve paragraph cohesion.",sentences:["The pūkeko is a bold and territorial bird. The pūkeko will often chase away much larger animals. The pūkeko's bright red beak makes the pūkeko easy to spot in wetland areas. Despite the pūkeko's aggression, the pūkeko is a beloved part of the New Zealand landscape."],prompt:"Which nouns can be replaced with pronouns? Are there any where replacing would cause confusion?"},{title:"You Do — Your Turn",instruction:"Rewrite this paragraph so pronouns link the sentences without causing ambiguity.",tasks:["The kākāpō is a large, flightless parrot. The kākāpō is critically endangered. Conservation teams monitor every single kākāpō. Each kākāpō has a name and a tracking pack. The tracking pack helps conservation teams follow each kākāpō's movements across the island.","✦ Bonus: Write a paragraph of 5 sentences about a NZ animal or place. Use a different pronoun in at least three sentences to link back to the subject. Make sure every pronoun is unambiguous."]},[{code:"Writing — Text Structure (Practice)",label:"Pronoun cohesion within paragraphs",detail:'NZC Phase 2 Writing — Text Structure (Practice): Students are expected to "use cohesive devices — including pronouns, synonyms, and connectives — to link ideas within and across sentences and paragraphs." This lesson focuses specifically on pronoun cohesion: using personal pronouns (it, they), possessive pronouns (its, their), and demonstrative pronouns (this, these) to refer back to nouns and ideas — creating flow rather than repetition.'},{code:"Writing — Sentence Structure (Knowledge)",label:"Pronoun reference & ambiguity",detail:'NZC Phase 2 Writing — Sentence Structure (Knowledge): "Pronouns must refer unambiguously to their antecedent. When two or more nouns are present, pronouns can create confusion if the referent is unclear." This lesson develops the habit of checking pronoun reference — drawing arrows from each pronoun to its antecedent — and revising when the reference is ambiguous.'}]),Thursday:g("Editing: identifying weak sentence openings","Writing — Writing Process (Practice) & Sentence Structure (Practice): students diagnose monotonous sentence opening patterns and revise them using fronted adverbials, adjective openers, and rearranged clause order.",{title:"I Do — The Weak Opening Pattern",instruction:'When every sentence starts the same way — especially with "The" or "I" — writing becomes monotonous. Watch me diagnose a passage with weak openings and revise it.',example:'"The sky was dark. The clouds gathered quickly. The wind picked up. The rain began to fall. The thunder rolled in from the south."',demonstration:'Five sentences. Every one starts with "The." Revision: "Dark clouds gathered quickly. As the wind picked up, the first drops of rain began to fall. From the south, thunder rolled in — low and threatening." Varied openers: adjective, adverbial, fronted phrase. Immediately more dynamic.',tip:"List the first word of every sentence in your paragraph. If more than two start the same way — vary them."},{title:"We Do — Diagnose Together",instruction:"List the first word of each sentence. Identify the pattern. Then rewrite three sentences with different openers.",sentences:["I arrived at school early. I put my bag in my locker. I went to find my friends. I sat down and waited for the bell. I felt nervous about the day ahead."],prompt:"What pattern do you see? What three different ways could you begin these sentences instead?"},{title:"You Do — Your Turn",instruction:"Rewrite this paragraph, varying the sentence openings so no two consecutive sentences start the same way.",tasks:["The match started well. The team scored early. The crowd cheered loudly. The other team fought back. The score was level at half time. The players looked tired. The coach spoke to them firmly. The second half began.","✦ Bonus: Write a paragraph of 6 sentences about any topic. Make a rule: no two sentences may start with the same word. List the opening word of each sentence underneath."]},[{code:"Writing — Writing Process (Practice)",label:"Revising for sentence opener variety",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing… making changes to vocabulary, punctuation, and structure to improve clarity and impact." This lesson teaches a specific diagnostic strategy — listing the first word of every sentence — that makes repetitive opener patterns immediately visible, enabling targeted revision.'},{code:"Writing — Sentence Structure (Practice)",label:"Varying sentence openers",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "vary sentence openings to avoid repetition and create effect," using fronted adverbials, adjective openers, and rearranged clause order. This lesson consolidates all sentence variety strategies from Terms 1 and 2, applying them in a revision context where students must diagnose the problem before selecting the solution.'}])},10:{Monday:g("Review: Term 2 punctuation","Writing — Punctuation (Knowledge & Practice): students consolidate all punctuation covered in Term 2 — commas after fronted adverbials, colons, semicolons, brackets, dashes, apostrophes for contraction, and comma splices.",{title:"I Do — Term 2 Punctuation Gallery",instruction:"Let's revisit every punctuation mark from Term 2 and its rule.",example:"Comma after fronted adverbial | Colon before list | Semicolon joining related sentences | Brackets for quiet aside | Dashes for emphatic aside | Contraction apostrophe | No apostrophe for plurals | Comma splice fix",demonstration:'"Before the match began, the referee called the captains together. Each team needed the following things: a captain, a strategy, and confidence. The home team was ready; the visitors looked nervous. One player — the one who had trained hardest — stepped forward."',tip:"For each mark, ask: what job is it doing here? If it's not doing a job, remove it."},{title:"We Do — Punctuation Challenge",instruction:"Add the correct punctuation to each sentence and name the rule.",sentences:["Despite the strong wind the waka race continued as planned.","The pā required three things a strong location high walls and clear sightlines.","The tī kōuka also known as the cabbage tree is found throughout Aotearoa."],prompt:"Which marks are needed and why? Could any sentence use more than one type?"},{title:"You Do — Your Turn",instruction:"Add all missing punctuation to this passage. Name every rule you applied.",tasks:["although the weather was overcast the school cross-country went ahead as planned. the course covered three different terrains the playing field a bush track and the school road. hazel our fastest runner had trained every morning before school. she wasnt nervous she was ready. after two kilometres hazel was still in front the other runners couldnt keep up with her pace.","✦ Bonus: Write a paragraph of 6 sentences that uses every Term 2 punctuation mark at least once. Label each one."]},[{code:"Writing — Punctuation (Knowledge)",label:"Term 2 punctuation review",detail:"NZC Phase 2 Writing — Punctuation (Knowledge): Students consolidate all punctuation covered in Term 2: commas after fronted adverbials, colons to introduce lists or explanations, semicolons to join related independent clauses, brackets and dashes for parenthetical information, apostrophes for contraction (not for plurals), and the identification and correction of comma splices. Review ensures students can name the function of each mark and apply the relevant rule."},{code:"Writing — Punctuation (Practice)",label:"Applying full range of punctuation",detail:'NZC Phase 2 Writing — Punctuation (Practice): Students are expected to "use a range of punctuation accurately and for effect." This consolidation lesson asks students to apply all Term 2 punctuation conventions in an extended passage — naming the rule behind each choice — building the metacognitive awareness needed to make punctuation decisions independently across all writing contexts at Phase 2.'}]),Tuesday:g("Review: Term 2 grammar","Writing — Sentence Structure (Knowledge): students consolidate all grammar covered in Term 2 — collective and abstract nouns, future tense, SVA tricky cases, relative pronouns, progressive tenses, and conjunction types.",{title:"I Do — Term 2 Grammar Gallery",instruction:"Let's revisit every grammar concept from Term 2 — one mini-example each.",example:"Collective & abstract nouns | Future tense: will/going to | SVA: everyone/each | Relative pronouns: who/which/that | Progressive tenses: was-ing/is-ing | Conjunction types: CO vs SUB",demonstration:'"A pride of lions (collective) shows remarkable loyalty (abstract). Each lion (SVA: singular) has its own role. The pride is going to move (future: planned) at dusk. The leader, who guides (relative: person) the hunt, was circling (past progressive) the herd when the weakest animal stumbled (simple past interrupts)."',tip:"Grammar is about understanding why a sentence works, not just labelling. Always connect the rule to the meaning it creates."},{title:"We Do — Grammar Challenge",instruction:"For each sentence, identify the grammar feature underlined and explain what rule it follows.",sentences:["A <u>flock</u> of starlings was swooping across the estuary.","<u>Neither</u> of the answers is correct.","The taonga, <u>which</u> had been in the whānau for generations, was carefully restored."],prompt:"What type of noun/pronoun/verb is underlined? What rule governs it?"},{title:"You Do — Your Turn",instruction:"Complete the grammar review tasks.",tasks:["Write a sentence using a collective noun and an abstract noun.",'Write two future tense sentences — one with "will" (spontaneous) and one with "going to" (planned).','Write a sentence using a relative clause with "which" (remember the commas).',"Write a sentence using past progressive interrupted by simple past.","✦ Bonus: Write a paragraph of 6 sentences demonstrating at least 5 different Term 2 grammar concepts. Label them in the margin."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"Term 2 grammar review",detail:"NZC Phase 2 Writing — Sentence Structure (Knowledge): Students consolidate their understanding of all grammar covered in Term 2: collective and abstract nouns, future tense using will/going to, subject-verb agreement with indefinite pronouns (everyone, each, neither), relative pronouns (who, which, that), past and present progressive tenses, and the distinction between coordinating and subordinating conjunctions. Review connects knowledge to meaning and use."},{code:"Writing — Sentence Structure (Practice)",label:"Integrated grammar application",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write grammatically correct sentences using a range of word classes and structures." This review lesson asks students to demonstrate all Term 2 grammar knowledge in context — combining multiple features in single sentences — moving from isolated recognition to integrated, purposeful use at Phase 2.'}]),Wednesday:g("Review: Term 2 sentence structures","Writing — Sentence Structure (Practice): students consolidate all sentence structures from Term 2 — compound sentences in new contexts, complex sentences using although/unless/while, sentence combining, and fronted adverbial sentences.",{title:"I Do — The Term 2 Sentence Toolkit",instruction:"This term we added powerful new tools to our sentence toolkit. Let me show each one in action.",example:"FANBOYS in context | Complex: although/unless/while | Combined sentences | Fronted adverbials | Who/where/when expanded",demonstration:'"Although the hīkoi had been going for three days, the marchers showed no sign of stopping (although). They would not rest unless they reached the marae (unless). While the leaders held talks, the rest of the group set up camp (while). Before dawn the next morning, they set out again (fronted adverbial)."',tip:"Variety is the goal. Read your writing aloud — if it has a rhythm that changes and shifts, you're using your toolkit well."},{title:"We Do — Sentence Type Identification",instruction:"Identify the sentence type and explain the structural feature that defines it.",sentences:["Despite the forecast, the outdoor event went ahead without a hitch.","She wanted to give up, yet something kept her moving forward.","The waka, which had been carved by hand over two years, was finally blessed."],prompt:"What type is each sentence? What structural feature tells you?"},{title:"You Do — Your Turn",instruction:"Write one sentence of each type, all on the topic of the sea.",tasks:['Compound sentence using "yet."','Complex sentence starting with "Although."','Complex sentence using "unless" — subordinate clause second.','Complex sentence using "while."',"Fronted adverbial sentence.","✦ Bonus: Combine all five sentences into a cohesive paragraph about the sea. Edit for flow and variety."]},[{code:"Writing — Sentence Structure (Practice)",label:"Term 2 sentence structure review",detail:"NZC Phase 2 Writing — Sentence Structure (Practice): Students consolidate all sentence structures from Term 2: FANBOYS compound sentences in varied contexts, complex sentences using although/unless/while, combining choppy sentences for flow, and fronted adverbial sentences with correct comma placement. Students demonstrate the ability to identify structural features by name and produce each type on demand."},{code:"Writing — Composing (Practice)",label:"Sentence variety across a paragraph",detail:'NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader," including controlling rhythm and variety through sentence structure. This consolidation task — writing five different sentence types on the same topic and combining them into a paragraph — directly tests whether students can select the right structure for each moment rather than defaulting to a favourite pattern.'}]),Thursday:g("Full-passage edit: Term 2 checklist","Writing — Writing Process (Practice): students apply all Term 2 editing skills in a systematic multi-pass edit, using the full Term 2 checklist to revise a passage for punctuation, grammar, vocabulary, and structure.",{title:"I Do — The Full Term 2 Edit",instruction:"Today I do a complete multi-pass edit using our full Term 2 checklist. One pass per focus — never try to fix everything at once.",example:"Pass 1: Comma after fronted adverbials | Pass 2: Colons, semicolons, brackets, dashes | Pass 3: Apostrophes (possession AND contraction — no plurals) | Pass 4: Comma splices | Pass 5: Vague verb/word upgrades | Pass 6: Sentence opener variety",demonstration:"I read the passage once for meaning. Then Pass 1: check every sentence that starts with an adverbial phrase — is the comma there? Pass 2: look for lists — do they use colons correctly? Pass 3: every apostrophe — possession, contraction, or error? And so on.",tip:"Multi-pass editing catches more than single-pass. Each pass has a specific focus — you're not trying to see everything at once."},{title:"We Do — Class Edit",instruction:"Work through each pass together on this passage.",sentences:["despite the rain our school fair went ahead last saturday. the organisers needed three things good volunteers lots of stalls and the right attitude. the fair included many activities a cake stall a bouncy castle a talent show and a silent auction. it wasnt perfect but everyones effort paid off. by the end of the afternoon the school had raised over two thousand dollars for the librarys new books."],prompt:"Pass by pass — what are we fixing? Count the total improvements."},{title:"You Do — Your Turn",instruction:"Edit this passage using all six passes of the Term 2 checklist. Rewrite the improved version.",tasks:["on thursday afternoon the year 5 and 6 students went to the wetland reserve near school. the reserve contained many things native plants birds insects and a small stream. although the track was muddy the students werent put off. the guide who had worked there for twenty years showed them a bittern its one of new zealands rarest birds. everyone said it was the best trip theyd ever been on.","✦ Bonus: Apply the full 6-pass edit to a paragraph from your own writing journal."]},[{code:"Writing — Writing Process (Practice)",label:"Multi-pass editing: Term 2 checklist",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing… making changes to vocabulary, punctuation, and structure to improve clarity and impact." This lesson makes the revision process systematic and visible — a structured, six-pass approach that integrates every editing skill from Term 2. Students apply punctuation, grammar, and vocabulary knowledge simultaneously in a single extended editing task.'},{code:"Writing — Writing Process (Practice)",label:"Term 2 skills: integrated application",detail:'NZC Phase 2 Writing — Writing Process (Practice): This consolidation lesson asks students to demonstrate mastery of all Term 2 writing skills in one editing task: fronted adverbial commas, colons and semicolons, brackets and dashes, apostrophes, comma splice correction, vocabulary precision, and sentence opener variety. It directly mirrors the Phase 2 expectation that students "apply writing knowledge and skills across a range of text types and purposes" with increasing independence.'}])}};
